const i = $input.first().json;

function s(v) {
  const t = (v === null || v === undefined) ? '' : String(v).trim();
  return t.length ? t : null;
}
function n(v) {
  if (v === null || v === undefined || v === '') return null;
  const x = Number(v);
  return isFinite(x) ? x : null;
}

const bedroomsRaw = s(i.bedrooms);
const bedrooms = (bedroomsRaw === null || bedroomsRaw.toLowerCase() === 'any') ? null : (isFinite(Number(bedroomsRaw)) ? Math.floor(Number(bedroomsRaw)) : null);

const areaRaw = s(i.area);
const area = (areaRaw && areaRaw.toLowerCase() !== 'any') ? areaRaw.toLowerCase() : null;

const budgetMin = n(i.budget_min);
const budgetMax = n(i.budget_max);
let mid = null;
if (budgetMin !== null && budgetMax !== null) mid = (budgetMin + budgetMax) / 2;
else if (budgetMax !== null) mid = budgetMax;
else if (budgetMin !== null) mid = budgetMin;

const yearRaw = s(i.handover_year);
const year = (yearRaw && /^[0-9]{4}$/.test(yearRaw)) ? yearRaw : null;

const lim = n(i.limit);

return [{ json: {
  market_id: s(i.market_id),
  budget_min: budgetMin,
  budget_max: budgetMax,
  bedrooms: bedrooms,
  area: area,
  handover_year: year,
  developer: s(i.developer),
  project_name: s(i.project_name),
  midpoint: mid,
  row_limit: (lim !== null && lim > 0) ? Math.min(Math.floor(lim), 20) : 3
} }];

const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.project_id; });

function num(v) { return (v === null || v === undefined || v === '') ? null : Number(v); }

const results = rows.map(function (r) {
  return {
    project_id: r.project_id,
    name: r.name,
    developer: r.developer,
    area: r.area,
    handover_quarter: r.handover_quarter,
    payment_plan: r.payment_plan,
    resale_threshold_pct: num(r.resale_threshold_pct),
    gross_yield_estimate: num(r.gross_yield_estimate),
    bedrooms: num(r.bedrooms),
    price_from: num(r.price_from),
    price_to: num(r.price_to)
  };
});

return [{ json: { ok: true, count: results.length, results: results } }];
